raw:
{
  "spells": [
    {
      "id": "spell_earth_01",
      "theory": "辨壤术将魔力沿指尖压入土粒缝隙，借不同土粒的密实程度回传细微震动差异。施术者通过掌心麻木感的分布，分辨黏土、沙土或腐殖土。魔力只在接触的土内传递，松散堆积或混入碎石时回传混乱。效果持续三十秒，只针对手中一把土，无法追溯土来自哪块地或归谁所有。",
      "casting": "单膝跪地，右手抓起一把土，掌心贴紧土块，以拇指在土表画一道短弧并注入魔力，静候掌心传来均匀麻感。",
      "failure": "土块过于干燥时会突然碎裂散落，魔力随之退回掌心，只留下短暂刺痛。若土中混有腐叶，麻感会变成断续跳动，施术者可能误判为沙质土，实际却是夹带碎屑的黏土。",
      "counters": [
        "向土样泼水使其黏结成团，土粒震动被水膜吸收，无法回传。",
        "把土样与粗砂按等量混合，回传麻感变得杂乱，难以分辨。"
      ],
      "socialConsequences": "河谷农户常请施术者帮忙判断新开菜地适合种什么，乡约见证下按次付几枚铜币。陶匠会雇人辨明坯土含砂量，但发现有人借辨壤偷探邻家田界时，乡老会要求当众解释并把土样交回。城市公会记录土壤买卖前也要求出具辨壤结果，却须先获得地主口头同意才可取样。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "刚入门时掌心麻感微弱，常把黏土误判为沙土。",
        "能稳定区分沙土与黏土，仍需反复确认。",
        "可辨出腐殖土占比，三十秒内完成判断。",
        "触土即知质地，结果与老农经验一致。"
      ]
    },
    {
      "id": "spell_earth_02",
      "theory": "松土术把魔力送入表层土壤，使相邻土粒短暂排斥，从而撑开板结的耕土。魔力只作用于接触点周围一小片，深度不超过一掌。松土后土壤仍留在原处，不会翻动或排出石块，也不会把种子埋好。效果持续三十秒，三十秒后土粒重新靠拢，松开的空隙逐渐消失。",
      "casting": "双手插入土中，十指张开，以腕部轻压土面，同时从掌心缓缓送出魔力，感觉到土粒向外让开即可收手。",
      "failure": "魔力送出过快时，土面会鼓起几个小包然后塌陷，板结层并未真正松开。若土中夹有大量草根，魔力会沿根须散走，只松动表面浮土，下层依旧坚硬，施术者可能误以为已经完成。",
      "counters": [
        "在目标土面洒一层粗砾，砾石隔断魔力传递，松土范围大幅缩小。",
        "提前用石磙压实并浇水，土粒重新黏结，排斥力难以撑开。"
      ],
      "socialConsequences": "河谷春耕时邻居常互相借用松土术，乡约要求施术者先问明地块归属，避免误松他人秧田。城市近郊菜农会付钱请人松土，但公会提醒不得在公共道路旁随意施放，以免路基变软。港口仓库地面若需松土，须经仓主同意，否则可能影响货堆稳定而被追究责任。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时土面只鼓起小包，松土深度很浅。",
        "能均匀松开一掌深的耕土，仍需检查硬块。",
        "三十秒内可处理一小块菜畦，松土较平整。",
        "出手即松透表层，不伤及邻垄，效率稳定。"
      ]
    },
    {
      "id": "spell_earth_03",
      "theory": "压印术将魔力聚在掌心，再按入软土，使土粒沿魔力分布紧密排列，留下与掌面或模具相同的清晰印痕。魔力只改变接触面附近的土粒排列，不改变土的颜色或成分。印痕在干燥前可被雨水冲淡，效果持续三十秒后魔力消散，印痕仍作为普通痕迹留在土中，但不再受法术维持。",
      "casting": "手掌或模具贴住软土，五指张开，以指根为支点缓缓下压，同时从掌心送出魔力，感到土面微微发硬即可抬起。",
      "failure": "下压过快时，土面会向四周挤裂，印痕边缘模糊成一片，无法辨认。若土太湿，魔力会使泥浆外溢，印痕变成一滩浅坑；施术者若强行重复，可能把原有足迹也压坏。",
      "counters": [
        "在软土上撒一层干沙，沙粒隔开魔力，印痕无法紧密成形。",
        "用湿布覆盖土面，水分使土粒滑动，压出的纹路随即模糊。"
      ],
      "socialConsequences": "河谷乡约见证土地转让时，常让双方在软土上压印为凭，事后由乡老保管印板。城市公会记录货箱底印时也允许使用，但要求先获得货主同意。港口理货员用压印核对货堆位置，若有人未经许可在他人货区压印，会被视为试图伪造货记而追究责任。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学压印常边缘模糊，需重压两三次才成形。",
        "能留下清晰掌印，但深浅略有不均。",
        "三十秒内可压出完整印模，纹路分明。",
        "一按即得清晰印痕，不损周围土面。"
      ]
    }
  ]
}
